 * Create a chunk longer than XML_PARSER_BIG_BUFFER_SIZE (300) ending
 * with an incomplete UTF-8 sequence.
 */
buf = xmlMalloc(1000 * 2 + 1);
for (i = 0; i < 2000; i += 2)
    memcpy(buf + i, "\xCE\xB1", 2);
buf[i] = '\xCE';
xmlParseChunk(ctxt, buf, 2001, 0);
xmlFree(buf);

xmlParseChunk(ctxt, "\xB1</d>", 4, 0);
